<script>
const clientData=@json($panelData),modals=[...document.querySelectorAll('.app-modal')];let lastTrigger=null;function openModal(id,trigger=null){lastTrigger=trigger;const modal=document.getElementById(id);modal.classList.remove('hidden');document.body.style.overflow='hidden';setTimeout(()=>modal.querySelector('button,a,input,select')?.focus(),30)}function closeModal(modal){modal.classList.add('hidden');if(!modals.some(item=>!item.classList.contains('hidden')))document.body.style.overflow='';lastTrigger?.focus()};document.querySelectorAll('[data-open-modal]').forEach(button=>button.addEventListener('click',()=>openModal(button.dataset.openModal,button)));document.querySelectorAll('[data-close-modal]').forEach(button=>button.addEventListener('click',()=>closeModal(button.closest('.app-modal'))));document.addEventListener('keydown',event=>{if(event.key==='Escape'){const open=modals.find(item=>!item.classList.contains('hidden'));if(open)closeModal(open)}});
const quickSearch=document.getElementById('client-quick-search'),searchInput=document.getElementById('client-search-input'),clearSearch=document.getElementById('clear-client-search');let searchTimer;searchInput.addEventListener('input',()=>{clearTimeout(searchTimer);clearSearch.classList.toggle('hidden',!searchInput.value);searchTimer=setTimeout(()=>quickSearch.requestSubmit(),350)});quickSearch.addEventListener('submit',()=>clearTimeout(searchTimer));clearSearch.addEventListener('click',()=>{searchInput.value='';clearSearch.classList.add('hidden');quickSearch.requestSubmit()});
function showClient(id,trigger){const c=clientData[id];if(!c)return;document.getElementById('modal-initials').textContent=c.name.split(' ').slice(0,2).map(v=>v[0]).join('');document.getElementById('modal-risk').textContent=c.risk;document.getElementById('modal-client-name').textContent=c.name;document.getElementById('modal-code').textContent=`${c.code} · ${c.status}`;for(const [key,value] of Object.entries({identity:c.identity,seller:c.seller,loan:c.activeLoan||'Sin crédito activo',balance:c.balance?`C$ ${Number(c.balance).toLocaleString('es-NI',{minimumFractionDigits:2})}`:'C$ 0.00',next:c.nextDue||'Sin cuota',available:`C$ ${Number(c.available).toLocaleString('es-NI',{minimumFractionDigits:2})}`,assets:`${c.assets} registrados`,guarantor:c.guarantor||'Sin fiador',phone:c.phone,email:c.email,address:c.address,last:`Última actividad: ${c.lastActivity}`}))document.getElementById(`modal-${key}`).textContent=value;for(const [key,url] of Object.entries({show:c.showUrl,edit:c.editUrl,application:c.applicationUrl,'loan-url':c.loanUrl,collection:c.collectionUrl})){const link=document.getElementById(`modal-${key}`);link.href=url||'#';link.classList.toggle('pointer-events-none',!url);link.classList.toggle('opacity-50',!url)}openModal('client-modal',trigger)}document.querySelectorAll('.client-row').forEach(row=>{row.addEventListener('click',()=>showClient(row.dataset.clientId,row));row.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();showClient(row.dataset.clientId,row)}})});
</script>
